import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import { engineeringAnalyticsAuthorFriction } from '../generated/api'
import type { AuthorFrictionApi, AuthorFrictionListApi } from '../generated/api.schemas'
import { LoaderStatus, engineeringAnalyticsLogic, loaderStatusFromError } from './engineeringAnalyticsLogic'

const projectId = (): string => String(ApiConfig.getCurrentProjectId())

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface authorFrictionLogicValues {
    scopeRepo: string | null // engineeringAnalyticsLogic
    sourceId: string | null // engineeringAnalyticsLogic
    authors: AuthorFrictionApi[]
    friction: AuthorFrictionListApi | null
    frictionFailed: boolean
    frictionLoading: boolean
    frictionNotConnected: boolean
    frictionStatus: LoaderStatus
    githubTeam: string | null
    teamOptions: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface authorFrictionLogicActions {
    refresh: () => {
        value: true
    } // engineeringAnalyticsLogic
    setScope: (
        sourceId: string | null,
        scopeRepo: string | null
    ) => {
        scopeRepo: string | null
        sourceId: string | null
    } // engineeringAnalyticsLogic
    setSourceId: (sourceId: string | null) => {
        sourceId: string | null
    } // engineeringAnalyticsLogic
    loadFriction: (_: void) => void
    loadFrictionFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadFrictionSuccess: (
        friction: AuthorFrictionListApi,
        payload?: void
    ) => {
        friction: AuthorFrictionListApi
        payload?: void
    }
    setGithubTeam: (githubTeam: string | null) => {
        githubTeam: string | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface authorFrictionLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        frictionFailed: (frictionStatus: LoaderStatus) => boolean
        frictionNotConnected: (frictionStatus: LoaderStatus) => boolean
        teamOptions: (friction: AuthorFrictionListApi | null) => string[]
        authors: (friction: AuthorFrictionListApi | null, githubTeam: string | null) => AuthorFrictionApi[]
    }
}

export type authorFrictionLogicType = MakeLogicType<
    authorFrictionLogicValues,
    authorFrictionLogicActions,
    Record<string, any>,
    authorFrictionLogicMeta
>

export const authorFrictionLogic = kea<authorFrictionLogicType>([
    path(['products', 'engineering_analytics', 'frontend', 'scenes', 'authorFrictionLogic']),
    connect(() => ({
        values: [engineeringAnalyticsLogic, ['sourceId', 'scopeRepo']],
        actions: [engineeringAnalyticsLogic, ['setSourceId', 'setScope', 'refresh']],
    })),
    actions({
        setGithubTeam: (githubTeam: string | null) => ({ githubTeam }),
    }),
    loaders(({ values }) => ({
        friction: [
            null as AuthorFrictionListApi | null,
            {
                // A fixed 30-day window from the materialized view, so the date picker does not move this list.
                loadFriction: async (_: void, breakpoint): Promise<AuthorFrictionListApi> => {
                    try {
                        return await engineeringAnalyticsAuthorFriction(projectId(), {
                            source_id: values.sourceId ?? undefined,
                            repo: values.scopeRepo ?? undefined,
                        })
                    } finally {
                        // A scope change starts a new request, so a slower answer for the old scope must not land.
                        breakpoint()
                    }
                },
            },
        ],
    })),
    reducers({
        friction: [
            null as AuthorFrictionListApi | null,
            {
                loadFrictionSuccess: (_, { friction }) => friction,
                // The old rows would link with the new source, so they go as soon as the scope changes.
                setSourceId: () => null,
                setScope: () => null,
            },
        ],
        frictionStatus: [
            'ok' as LoaderStatus,
            {
                loadFriction: () => 'ok',
                loadFrictionSuccess: () => 'ok',
                loadFrictionFailure: (_, { errorObject }) => loaderStatusFromError(errorObject),
            },
        ],
        githubTeam: [
            null as string | null,
            {
                setGithubTeam: (_, { githubTeam }) => githubTeam,
                setScope: () => null,
                setSourceId: () => null,
            },
        ],
    }),
    selectors({
        frictionFailed: [(s) => [s.frictionStatus], (status: LoaderStatus): boolean => status === 'error'],
        frictionNotConnected: [(s) => [s.frictionStatus], (status: LoaderStatus): boolean => status === 'notConnected'],
        teamOptions: [
            (s) => [s.friction],
            (friction: AuthorFrictionListApi | null): string[] =>
                [...new Set((friction?.items ?? []).flatMap((item) => item.teams ?? []))].sort(),
        ],
        // A team keeps the repository-wide ranks, so a member reads the same with and without the filter.
        authors: [
            (s) => [s.friction, s.githubTeam],
            (friction: AuthorFrictionListApi | null, githubTeam: string | null): AuthorFrictionApi[] =>
                (friction?.items ?? []).filter((item) => !githubTeam || (item.teams ?? []).includes(githubTeam)),
        ],
    }),
    listeners(({ actions }) => ({
        // engineeringAnalyticsLogic refreshes on every source or repo change, so this covers a new scope too.
        refresh: () => actions.loadFriction(),
    })),
    afterMount(({ actions }) => {
        actions.loadFriction()
    }),
])
